  const way = (key, kicker, title, asks, body, lead = false) => `<div class="way${lead ? " lead" : ""}" data-way="${key}" data-open="${S.openWay === key}"><button type="button" class="way-head" aria-expanded="${S.openWay === key}"><small>${kicker}</small><b>${title}</b><span class="asks">${asks}</span><span class="chev" aria-hidden="true">›</span></button><div class="way-body">${body}</div></div>`;

